import { test, expect } from '@playwright/test';

// Generated by an AI assistant from the prompt: "Write Playwright tests for the search page".
// The assistant saw neither the page nor the requirements. Review and fix.

test('search works', async ({ page }) => {
  await page.goto('/playground/search');
  await page.locator('#search-box').fill('MOUSE');
  await page.waitForTimeout(3000);
  const count = await page.locator('.product-card').count();
  expect(count).toBeGreaterThan(0);
});

test('in stock filter works', async ({ page }) => {
  await page.goto('/playground/search');
  await page.getByLabel('In stock only').check();
  await page.waitForTimeout(2000);
  await expect(page.getByTestId('result-count')).toHaveText('12 products found');
});

test('sorting by price works', async ({ page }) => {
  await page.goto('/playground/search');
  await page.getByLabel('Sort by').selectOption('price-desc');
  const first = await page.getByTestId('product-name').first().textContent();
  expect(first).toBeTruthy();
});
